use std::{path::Path,sync::Arc};
use dq_analyze::{captured_raw_tree_pages::{Policy,Data},captured_generator_budget::Budget,captured_reactive_reads::Failure};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>}
impl dq_analyze::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,dq_analyze::captured_raw_file::RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{for(relative,text)in &self.rows{if !dq_analyze::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
struct Text<'a>(&'a Data);impl baseline::SiteText for Text<'_>{fn site_text(&self,rel:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(site,_)|site.rel==rel&&site.line as usize==line).expect("actual doc source text").1.clone()}}
fn record(outcome:&dq_analyze::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn failure(error:Failure)->Box<dyn std::error::Error>{match error{Failure::Operational(actual)=>Box::new(actual),Failure::Unsupported(message)=>message.into()}}

fn strict_original_header_projection()->Result<(),Box<dyn std::error::Error>>{
 let mut cases:Vec<String>=vec![
 "/proc/global_name(a, var/list/b = list(1, list(2,3)))\n    return\n/datum/a/proc/member(x as text|num)\n    return\n/datum/a/verb/open() as num\n    return\n".into(),
 "/datum/a/override(\\\n    x, y)\n    return\n/datum/a/proc/multi(\n    var/list/items = list(1, 2),\n    var/z = list(\n        3, 4))\n    return\n".into(),
 "/datum/a/var/not_a_proc(x)\n/proc/bad(\n/datum/a/proc/after_bad()\n    return\n/proc/name() trailing\n/proc/valid() // comment\n    var/s = \"/proc/fake()\"\n".into(),
 "  /proc/indented()\n// /proc/comment()\n/* /proc/block() */\n/proc/α_unicode()\n    return\n/verb/action()\n    return\n/datum/a/proc/plain()\n\n\n/datum/b/proc/next()\n    return\n".into(),
 ];
 for n in [39usize,40,41,45]{let mut text=String::from("/datum/long/proc/balanced(\n");for _ in 0..n{text.push_str("    list(1),\n")}text.push_str("    value)\n    return\n/proc/tail()\n    return\n");cases.push(text);}
 for(case,text)in cases.iter().enumerate(){let f=tree::SourceFile::from_text("code/header.dm",text);let old=old_dx::procs_in(&f);let new=dq_analyze::dm::dx::procs_in(&f);let old_rows=old.iter().map(|p|(&p.rel,p.line,&p.path,&p.name,&p.params,p.body_start,p.body_len)).collect::<Vec<_>>();let new_rows=new.iter().map(|p|(&p.rel,p.line,&p.path,&p.name,&p.params,p.body_start,p.body_len)).collect::<Vec<_>>();assert_eq!(old_rows,new_rows,"whole original header record {case}");let mut projected=Vec::new();dq_analyze::dm::dx::visit_proc_names_using(&f,&mut dq_analyze::key_policy_control::Compatibility,|owner,name|{projected.push((owner.to_string(),name.to_string()));Ok(())}).unwrap();assert_eq!(projected,old.iter().map(|p|(p.path.clone(),p.name.clone())).collect::<Vec<_>>(),"exact name-only header projection {case}");}
 struct Stop{polls:usize};impl dq_analyze::key_policy_control::Control for Stop{type Error=std::io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Self::Error>{self.polls+=1;if self.polls==4{Err(std::io::Error::from_raw_os_error(1450))}else{Ok(())}}fn reserve(&mut self,_:usize)->Result<(),Self::Error>{Ok(())}fn overflow(&mut self)->Self::Error{std::io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->Self::Error{std::io::ErrorKind::OutOfMemory.into()}}
 let f=tree::SourceFile::from_text("code/header.dm",&cases[0]);let error=dq_analyze::dm::dx::visit_proc_names_using(&f,&mut Stop{polls:0},|_,_|Ok(())).unwrap_err();assert_eq!(error.raw_os_error(),Some(1450));Ok(())
}
fn main()->Result<(),Box<dyn std::error::Error>>{strict_original_header_projection()?;use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/doc_snippets_dx.rs"))),"96bbe29394ea1fabcccae2f89b91e71bc7ea1101");assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/doc_snippets_workspace.rs"))),"021b765b9cf2a02e3688a6b5f204ba3bfc221fb5");
 for case in 0..fixture::CASES{for raw in [false,true]{let root=test_scratch::dir(&format!("doc-snippets-old-{case}-{raw}"));let files=fixture::files(case);for(relative,text)in &files{let p=root.join(relative);std::fs::create_dir_all(p.parent().ok_or("parent")?)?;std::fs::write(p,text)?;}let configuration=fixture::configuration(case);let config_path=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(config_path.parent().ok_or("parent")?)?;std::fs::write(config_path,&configuration)?;
 let opts=dq_analyze::run::Options{root:root.clone(),lints:vec!["doc_snippets".into()],raw,no_cache:true,..Default::default()};let mut registry=lint::Registry::default();old::register(&mut registry);let original=dq_analyze::run::Engine::new(registry,opts.clone())?;let expected=original.run_one(original.reg.lints[0].as_ref());assert!(expected.internal_error.is_none());if case==0{assert!(!expected.run.sites.is_empty());assert!(!expected.allow_used.is_empty());}
 let mut registry=lint::Registry::default();dq_analyze::lints::doc_snippets::register(&mut registry);let shared=dq_analyze::run::Engine::new(registry,opts)?;assert_eq!(record(&shared.run_one(shared.reg.lints[0].as_ref())),record(&expected));
 let budget=Budget::new(256*1024*1024)?;let mut rows=Vec::new();for(relative,text)in files{if !Policy::DocSnippets.selects_path(relative){continue}let source=dm_preprocess::AcquiredSource::from_original_bytes(text.into_bytes(),());rows.push((relative.into(),source.lease().source_text().clone()));}rows.reverse();let pages=Pages{root:&root,rows,budget:Arc::clone(&budget)};let config=dq_analyze::captured_raw_file::Config::capture(dq_analyze::captured_raw_policy::Configuration::Captured(configuration.as_bytes()))?;let data=dq_analyze::captured_raw_tree_pages::collect(&pages,Policy::DocSnippets,&config,&budget,&||Ok(())).map_err(failure)?;assert_eq!(data.sites(),expected.run.sites);assert_eq!(data.allow_used(),expected.allow_used);assert_eq!(data.notes(),expected.run.notes);let empty=Default::default();let scope=config.borrowed_report_scope("doc_snippets",Policy::DocSnippets.metadata().group).unwrap_or(&empty);let run=lint::Run{sites:data.sites().to_vec(),notes:data.notes().to_vec()};let actual=dq_analyze::policy_finish::finish_report(Policy::DocSnippets.metadata(),scope,&Text(&data),run,data.allow_used().to_vec(),Default::default(),&root,&None,raw,|run,text,raw|dq_analyze::doc_snippets_policy::finish_summary(Policy::DocSnippets.metadata(),&root,&Text(&data),data.doc_blocks().expect("completed doc summaries"),run,text,raw),|_,_|false);assert_eq!(record(&actual),record(&expected),"whole old/native custom doc report {case}/{raw}");
 for mode in [baseline::Mode::Update,baseline::Mode::Migrate,baseline::Mode::Seed]{let path=root.join("tools/ci/doc_snippets_baseline.txt");let initial=fixture::files(case).into_iter().find(|(p,_)|*p=="tools/ci/doc_snippets_baseline.txt").map(|(_,v)|v);let reset=||->std::io::Result<()>{match &initial{Some(bytes)=>std::fs::write(&path,bytes),None=>match std::fs::remove_file(&path){Ok(())=>Ok(()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Ok(()),Err(e)=>Err(e)}}};reset()?;let old_text=original.update_baseline(original.reg.lints[0].as_ref(),mode)?;let old_bytes=std::fs::read(&path)?;reset()?;let native_text=dq_analyze::doc_snippets_policy::update_summary(Policy::DocSnippets.metadata(),&root,&Text(&data),data.doc_blocks().unwrap(),&actual.run,mode)?;assert_eq!(old_text,native_text,"exact Custom two-write report");assert_eq!(old_bytes,std::fs::read(&path)?,"exact Custom Seed/Migrate/Update bytes");}
 println!("DOC_SNIPPETS_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"case":case,"raw":raw,"record":record(&actual)}));}}
 Ok(())}
